import type { Register } from 'claude-code'

/**
 * SuperClaude++ function hooks.
 *
 * Rules that used to live only in RULES.md prose are enforced here, where the
 * engine applies them mechanically. Shell hooks (hooks.json) cover the rest.
 */
export const register: Register = on => {
  // RULES.md "Git Preferences — No Co-Authored-By": the harness composes a
  // commit trailer on its own; answering with an empty text drops it before
  // the model ever reads it. PR footers are left as the harness writes them.
  on('attribution.text', { kind: 'commit' }, () => ({ text: '' }))

  // Replaces the v3.3 InstructionsLoaded echo banner (whose stdout nobody saw).
  on('session.start', ($, e, next) => {
    if (e.isInteractive) $.ui.toast('SuperClaude++ loaded')
    return next(e)
  })
}

